using System;
using System.Collections.Generic;

namespace GildedFate.Theme
{
    /// <summary>A small RGBA image generated by code (straight alpha, row 0 at the top). Deterministic: the same inputs always give the same pixels.</summary>
    public sealed class ThemeImage
    {
        public readonly string id; public readonly int width, height; public readonly byte[] rgba;
        /// <summary>Border width in pixels that stays unscaled when the image is stretched as a 9-slice (0 = not a 9-slice).</summary>
        public readonly int slice;
        public readonly bool tiles;
        public ThemeImage(string id, int width, int height, int slice = 0, bool tiles = false) { this.id = id; this.width = width; this.height = height; this.slice = slice; this.tiles = tiles; rgba = new byte[width * height * 4]; }

        public ThemeColor Get(int x, int y) { var i = (y * width + x) * 4; return new ThemeColor(rgba[i] / 255f, rgba[i + 1] / 255f, rgba[i + 2] / 255f, rgba[i + 3] / 255f); }
        public void Set(int x, int y, ThemeColor c)
        {
            var i = (y * width + x) * 4;
            rgba[i] = B(c.r); rgba[i + 1] = B(c.g); rgba[i + 2] = B(c.b); rgba[i + 3] = B(c.a);
        }
        static byte B(float v) => (byte)Math.Round((v < 0 ? 0 : v > 1 ? 1 : v) * 255f);
    }

    /// <summary>The metals and glass of a frame: highlights, mid-tones, the groove inside the bevel, and the corner studs.</summary>
    public struct FramePalette
    {
        public ThemeColor metalHi, metalLo, groove, stud, hairline; public float innerShadow;
        static FramePalette Make(uint hi, uint lo, uint groove, uint stud, uint hairline, float shadow = .6f) =>
            new FramePalette { metalHi = ThemeColor.Hex(hi), metalLo = ThemeColor.Hex(lo), groove = ThemeColor.Hex(groove), stud = ThemeColor.Hex(stud), hairline = ThemeColor.Hex(hairline), innerShadow = shadow };
        public static readonly FramePalette Gold = Make(0xF7D98C, 0x7A4E14, 0x2A1A07, 0xFFE9A8, 0xE0B358);
        public static readonly FramePalette Bronze = Make(0xC79A58, 0x4A2F10, 0x1C1206, 0xE3BC78, 0x9C7436);
        public static readonly FramePalette Steel = Make(0xC9D3E0, 0x39404D, 0x11151C, 0xE6EEF8, 0x8896A8);
        public static readonly FramePalette Crimson = Make(0xFF8A70, 0x6B1710, 0x240806, 0xFFB09C, 0xD0503C);
        public static readonly FramePalette Azure = Make(0x8FC4FF, 0x1C4A86, 0x08162B, 0xBFE0FF, 0x4F8FDB);
        public static readonly FramePalette Violet = Make(0xC3A2FF, 0x442386, 0x150B2B, 0xDCC8FF, 0x8A5CE0);
        public static readonly FramePalette Jade = Make(0x7BE8C4, 0x136B52, 0x06231B, 0xB2F5DE, 0x34B58F);
    }

    /// <summary>Procedural image generators. Every shape here is plain arithmetic, so it can be checked by tests and previewed as a PNG.</summary>
    public static class ThemeImages
    {
        const float K = 0.70710678f;
        static float Clamp01(float v) => v < 0 ? 0 : v > 1 ? 1 : v;
        static float Smooth(float a, float b, float v) { var t = Clamp01((v - a) / (b - a)); return t * t * (3 - 2 * t); }
        /// <summary>Straight-alpha "over": top drawn over bottom.</summary>
        public static ThemeColor Over(ThemeColor top, ThemeColor bottom)
        {
            var a = top.a + bottom.a * (1 - top.a);
            if (a <= 1e-5f) return ThemeColor.Clear;
            return new ThemeColor((top.r * top.a + bottom.r * bottom.a * (1 - top.a)) / a, (top.g * top.a + bottom.g * bottom.a * (1 - top.a)) / a, (top.b * top.a + bottom.b * bottom.a * (1 - top.a)) / a, a);
        }

        // ---------------------------------------------------------------- gradients
        public struct Stop { public float t; public ThemeColor c; public Stop(float t, ThemeColor c) { this.t = t; this.c = c; } }

        /// <summary>A vertical gradient strip (top to bottom). Stretch it over any rectangle.</summary>
        public static ThemeImage Gradient(string id, int height, params Stop[] stops)
        {
            var img = new ThemeImage(id, 4, height);
            for (var y = 0; y < height; y++)
            {
                var t = height <= 1 ? 0 : y / (float)(height - 1);
                var c = stops[stops.Length - 1].c;
                for (var s = 0; s < stops.Length - 1; s++)
                    if (t <= stops[s + 1].t) { var span = Math.Max(1e-5f, stops[s + 1].t - stops[s].t); c = ThemeColor.Lerp(stops[s].c, stops[s + 1].c, (t - stops[s].t) / span); break; }
                if (t < stops[0].t) c = stops[0].c;
                for (var x = 0; x < 4; x++) img.Set(x, y, c);
            }
            return img;
        }

        /// <summary>A horizontal gradient strip (left to right).</summary>
        public static ThemeImage GradientH(string id, int width, params Stop[] stops)
        {
            var img = new ThemeImage(id, width, 4);
            for (var x = 0; x < width; x++)
            {
                var t = width <= 1 ? 0 : x / (float)(width - 1);
                var c = stops[stops.Length - 1].c;
                for (var s = 0; s < stops.Length - 1; s++)
                    if (t <= stops[s + 1].t) { var span = Math.Max(1e-5f, stops[s + 1].t - stops[s].t); c = ThemeColor.Lerp(stops[s].c, stops[s + 1].c, (t - stops[s].t) / span); break; }
                if (t < stops[0].t) c = stops[0].c;
                for (var y = 0; y < 4; y++) img.Set(x, y, c);
            }
            return img;
        }

        // ---------------------------------------------------------------- lights and shadows
        /// <summary>A soft round light: white, fading smoothly to nothing. Tint it warm for a torch glow, red for a danger pulse.</summary>
        public static ThemeImage Glow(string id, int size = 128, float power = 2.2f)
        {
            var img = new ThemeImage(id, size, size);
            for (var y = 0; y < size; y++) for (var x = 0; x < size; x++)
            {
                var dx = (x + .5f) / size * 2 - 1; var dy = (y + .5f) / size * 2 - 1; var r = (float)Math.Sqrt(dx * dx + dy * dy);
                img.Set(x, y, new ThemeColor(1, 1, 1, (float)Math.Pow(1 - Clamp01(r), power)));
            }
            return img;
        }

        /// <summary>A thin glowing ring (for selected map nodes, focus outlines, rarity halos).</summary>
        public static ThemeImage Ring(string id, int size = 128, float radius = .78f, float thickness = .07f, float softness = .08f)
        {
            var img = new ThemeImage(id, size, size);
            for (var y = 0; y < size; y++) for (var x = 0; x < size; x++)
            {
                var dx = (x + .5f) / size * 2 - 1; var dy = (y + .5f) / size * 2 - 1; var r = (float)Math.Sqrt(dx * dx + dy * dy);
                var d = Math.Abs(r - radius);
                var core = 1 - Smooth(thickness * .5f, thickness * .5f + 0.012f, d);
                var halo = (1 - Smooth(0, softness + thickness, d)) * .45f;
                img.Set(x, y, new ThemeColor(1, 1, 1, Math.Max(core, halo)));
            }
            return img;
        }

        /// <summary>A 9-slice drop shadow. Draw it under any rectangle, inflated by the blur radius, for real depth.</summary>
        public static ThemeImage Shadow9(string id, int size = 64, int core = 8)
        {
            var slice = (size - core) / 2; var img = new ThemeImage(id, size, size, slice);
            for (var y = 0; y < size; y++) for (var x = 0; x < size; x++)
            {
                float Fall(int p) { var dist = p < slice ? slice - p - .5f : p >= slice + core ? p - (slice + core) + .5f : 0f; return 1 - Smooth(0, slice, dist); }
                var a = Fall(x) * Fall(y);
                img.Set(x, y, new ThemeColor(0, 0, 0, a * a * .9f + a * .1f));
            }
            return img;
        }

        /// <summary>Darkens the edges of whatever it is stretched over.</summary>
        public static ThemeImage Vignette(string id, int size = 128, float inner = .38f, float strength = .9f)
        {
            var img = new ThemeImage(id, size, size);
            for (var y = 0; y < size; y++) for (var x = 0; x < size; x++)
            {
                var dx = (x + .5f) / size * 2 - 1; var dy = (y + .5f) / size * 2 - 1; var r = (float)Math.Sqrt(dx * dx + dy * dy) / 1.2f;
                img.Set(x, y, new ThemeColor(0, 0, 0, Smooth(inner, 1f, r) * strength));
            }
            return img;
        }

        /// <summary>Tiling film grain. Laid over a flat gradient at a few percent, it removes the plastic look and the banding.</summary>
        public static ThemeImage Grain(string id, int size = 128, int seed = 7)
        {
            var img = new ThemeImage(id, size, size, 0, true);
            float Hash(int x, int y) { unchecked { var h = (uint)(x * 374761393 + y * 668265263 + seed * 1442695041); h = (h ^ (h >> 13)) * 1274126177; return ((h ^ (h >> 16)) & 0xFFFF) / 65535f; } }
            float Noise(float fx, float fy, int cell)
            {
                var gx = fx / cell; var gy = fy / cell; var x0 = (int)Math.Floor(gx); var y0 = (int)Math.Floor(gy); var tx = gx - x0; var ty = gy - y0; var n = size / cell;
                float V(int xx, int yy) => Hash(((xx % n) + n) % n, ((yy % n) + n) % n);
                var a = V(x0, y0) + (V(x0 + 1, y0) - V(x0, y0)) * (tx * tx * (3 - 2 * tx)); var b = V(x0, y0 + 1) + (V(x0 + 1, y0 + 1) - V(x0, y0 + 1)) * (tx * tx * (3 - 2 * tx));
                return a + (b - a) * (ty * ty * (3 - 2 * ty));
            }
            for (var y = 0; y < size; y++) for (var x = 0; x < size; x++)
            {
                var v = Noise(x, y, 1) * .55f + Noise(x, y, 4) * .45f;
                img.Set(x, y, new ThemeColor(1, 1, 1, v * v));
            }
            return img;
        }

        /// <summary>A soft vertical band of light used to sweep across a button.</summary>
        public static ThemeImage Sheen(string id, int width = 64)
        {
            var img = new ThemeImage(id, width, 4);
            for (var x = 0; x < width; x++)
            {
                var t = (x + .5f) / width * 2 - 1; var a = (float)Math.Pow(1 - Math.Abs(t), 1.6);
                for (var y = 0; y < 4; y++) img.Set(x, y, new ThemeColor(1, 1, 1, a));
            }
            return img;
        }

        /// <summary>A small faceted diamond: the ornament at the heart of dividers and the corners of frames.</summary>
        public static ThemeImage Diamond(string id, FramePalette p, int size = 24)
        {
            var img = new ThemeImage(id, size, size); var c = (size - 1) / 2f; var r = size * .42f;
            for (var y = 0; y < size; y++) for (var x = 0; x < size; x++)
            {
                var dx = x - c; var dy = y - c; var d = Math.Abs(dx) + Math.Abs(dy);
                var cover = 1 - Smooth(r - .7f, r + .7f, d); if (cover <= 0) continue;
                var lit = Clamp01(.5f + (-dx - dy) / (2 * r)); // upper-left facets catch the light
                var col = ThemeColor.Lerp(p.metalLo, p.stud, lit);
                if (d < r * .28f) col = ThemeColor.Lerp(col, ThemeColor.White, .55f);
                if (d > r - 1.4f) col = ThemeColor.Lerp(col, new ThemeColor(.03f, .02f, .01f), .65f);
                img.Set(x, y, col.WithAlpha(cover));
            }
            return img;
        }

        // ---------------------------------------------------------------- frames
        /// <summary>Distance inward from the edge of a chamfered box (negative outside), and the outward-facing normal at the nearest edge.</summary>
        static float InsideDistance(float x, float y, float w, float h, float cut, out float nx, out float ny)
        {
            var best = x; nx = -1; ny = 0;
            var d = w - x; if (d < best) { best = d; nx = 1; ny = 0; }
            d = y; if (d < best) { best = d; nx = 0; ny = -1; }
            d = h - y; if (d < best) { best = d; nx = 0; ny = 1; }
            d = (x + y - cut) * K; if (d < best) { best = d; nx = -K; ny = -K; }
            d = ((w - x) + y - cut) * K; if (d < best) { best = d; nx = K; ny = -K; }
            d = (x + (h - y) - cut) * K; if (d < best) { best = d; nx = -K; ny = K; }
            d = ((w - x) + (h - y) - cut) * K; if (d < best) { best = d; nx = K; ny = K; }
            return best;
        }

        /// <summary>
        /// A chamfered, bevelled metal frame as a 9-slice: dark outline, lit bevel (bright on the upper left, dark on the lower right), a groove,
        /// an inner shadow that settles into the panel behind it, a fine inner hairline, and a stud in each corner. The middle is transparent.
        /// </summary>
        public static ThemeImage Frame9(string id, FramePalette p, int size = 64, int slice = 24, float cut = 10f)
        {
            var img = new ThemeImage(id, size, size, slice);
            for (var py = 0; py < size; py++) for (var px = 0; px < size; px++)
            {
                float x = px + .5f, y = py + .5f;
                var d = InsideDistance(x, y, size, size, cut, out var nx, out var ny);
                if (d <= -.5f) continue;
                var lit = Clamp01(.5f + .5f * (-nx * K - ny * K));
                var outer = Clamp01(d + .5f);

                var outline = new ThemeColor(.02f, .012f, .006f, .96f * (1 - Smooth(1.0f, 1.8f, d)) * outer);
                var bevelT = Clamp01((d - 1.2f) / 3f);
                var metal = ThemeColor.Lerp(p.metalLo, p.metalHi, lit).Mul(.82f + .3f * (1 - bevelT));
                if (lit > .8f && d < 2.6f) metal = ThemeColor.Lerp(metal, ThemeColor.White, .30f * (lit - .8f) / .2f);
                var bevel = metal.WithAlpha((Smooth(1.0f, 1.8f, d) * (1 - Smooth(4.0f, 4.8f, d))) * outer);
                var groove = p.groove.Mul(.7f + .6f * lit).WithAlpha(Smooth(4.0f, 4.8f, d) * (1 - Smooth(6.0f, 6.8f, d)) * .97f);
                var shadow = new ThemeColor(0, 0, 0, p.innerShadow * Smooth(5.8f, 6.6f, d) * (1 - Smooth(6.6f, 11.5f, d)));
                var hair = p.hairline.WithAlpha(.30f * Smooth(10.4f, 11f, d) * (1 - Smooth(11.4f, 12f, d)));

                var col = Over(hair, Over(shadow, Over(groove, Over(bevel, outline))));

                // corner studs (mirror every quadrant onto the upper left)
                float mx = Math.Min(x, size - x), my = Math.Min(y, size - y);
                if (mx < 22 && my < 22)
                {
                    var sd = Math.Abs(mx - 13f) + Math.Abs(my - 13f);
                    var ring = 1 - Smooth(4.2f, 5.0f, sd); var face = 1 - Smooth(3.0f, 3.8f, sd);
                    if (ring > 0)
                    {
                        // which quadrant am I in, so the highlight sits on the lit side of the stud
                        var sx = (x < size / 2f ? -1f : 1f) * (mx - 13f); var sy = (y < size / 2f ? -1f : 1f) * (my - 13f);
                        var sl = Clamp01(.5f + (-sx - sy) / 6f);
                        var studCol = ThemeColor.Lerp(p.metalLo, p.stud, sl);
                        if (sd < 1.3f) studCol = ThemeColor.Lerp(studCol, ThemeColor.White, .6f);
                        col = Over(studCol.WithAlpha(face), Over(new ThemeColor(.02f, .012f, .006f, .9f * ring), col));
                    }
                }
                img.Set(px, py, col);
            }
            return img;
        }

        /// <summary>A slim 9-slice rim (outline, two-pixel bevel, inner shadow) for bars, plates and small controls, where a full frame would be too heavy.</summary>
        public static ThemeImage Rim9(string id, FramePalette p, int size = 16, int slice = 6)
        {
            var img = new ThemeImage(id, size, size, slice);
            for (var py = 0; py < size; py++) for (var px = 0; px < size; px++)
            {
                float x = px + .5f, y = py + .5f;
                var d = InsideDistance(x, y, size, size, 2.2f, out var nx, out var ny);
                if (d <= -.5f) continue;
                var lit = Clamp01(.5f + .5f * (-nx * K - ny * K)); var outer = Clamp01(d + .5f);
                var outline = new ThemeColor(.02f, .012f, .006f, .95f * (1 - Smooth(.9f, 1.5f, d)) * outer);
                var bevel = ThemeColor.Lerp(p.metalLo, p.metalHi, lit).WithAlpha(Smooth(.9f, 1.5f, d) * (1 - Smooth(2.6f, 3.2f, d)) * outer);
                var shadow = new ThemeColor(0, 0, 0, .55f * Smooth(2.6f, 3.2f, d) * (1 - Smooth(3.2f, 5.6f, d)));
                img.Set(px, py, Over(shadow, Over(bevel, outline)));
            }
            return img;
        }
    }

    /// <summary>The theme's shared images, built once on first use.</summary>
    public static class ThemeAssets
    {
        static ThemeColor C(uint hex, float a = 1f) => ThemeColor.Hex(hex, a);
        static ThemeImages.Stop S(float t, ThemeColor c) => new ThemeImages.Stop(t, c);

        public static readonly ThemeImage FrameGold = ThemeImages.Frame9("frame.gold", FramePalette.Gold);
        public static readonly ThemeImage FrameBronze = ThemeImages.Frame9("frame.bronze", FramePalette.Bronze);
        public static readonly ThemeImage FrameSteel = ThemeImages.Frame9("frame.steel", FramePalette.Steel);
        public static readonly ThemeImage FrameCrimson = ThemeImages.Frame9("frame.crimson", FramePalette.Crimson);
        public static readonly ThemeImage FrameAzure = ThemeImages.Frame9("frame.azure", FramePalette.Azure);
        public static readonly ThemeImage FrameViolet = ThemeImages.Frame9("frame.violet", FramePalette.Violet);
        public static readonly ThemeImage FrameJade = ThemeImages.Frame9("frame.jade", FramePalette.Jade);

        public static readonly ThemeImage Shadow = ThemeImages.Shadow9("shadow.soft");
        public static readonly ThemeImage Glow = ThemeImages.Glow("glow.soft");
        public static readonly ThemeImage GlowTight = ThemeImages.Glow("glow.tight", 128, 3.4f);
        public static readonly ThemeImage Ring = ThemeImages.Ring("ring.glow");
        public static readonly ThemeImage Vignette = ThemeImages.Vignette("vignette");
        public static readonly ThemeImage Grain = ThemeImages.Grain("grain");
        public static readonly ThemeImage Sheen = ThemeImages.Sheen("sheen");
        public static readonly ThemeImage DiamondGold = ThemeImages.Diamond("diamond.gold", FramePalette.Gold);
        public static readonly ThemeImage RimBronze = ThemeImages.Rim9("rim.bronze", FramePalette.Bronze);
        public static readonly ThemeImage RimGold = ThemeImages.Rim9("rim.gold", FramePalette.Gold);
        public static readonly ThemeImage RimSteel = ThemeImages.Rim9("rim.steel", FramePalette.Steel);

        // Glass: the obsidian a panel is cut from. Slightly lifted at the top, deep at the bottom.
        public static readonly ThemeImage PanelGlass = ThemeImages.Gradient("glass.panel", 64, S(0, C(0x121A27, .96f)), S(.45f, C(0x090D15, .965f)), S(1, C(0x04060B, .975f)));
        public static readonly ThemeImage ButtonGlass = ThemeImages.Gradient("glass.button", 64, S(0, C(0x1B2433, .97f)), S(.5f, C(0x0B1019, .97f)), S(1, C(0x06080D, .97f)));
        public static readonly ThemeImage ButtonGlassHot = ThemeImages.Gradient("glass.button.hot", 64, S(0, C(0x4A3010, .97f)), S(.5f, C(0x2A1A08, .97f)), S(1, C(0x150C04, .97f)));
        public static readonly ThemeImage ButtonGlassPressed = ThemeImages.Gradient("glass.button.pressed", 64, S(0, C(0x120A03, .98f)), S(1, C(0x2A1A08, .98f)));
        public static readonly ThemeImage TopSheen = ThemeImages.Gradient("sheen.top", 32, S(0, ThemeColor.White.WithAlpha(.20f)), S(.5f, ThemeColor.White.WithAlpha(.05f)), S(1, ThemeColor.White.WithAlpha(0f)));
        public static readonly ThemeImage RuleFade = ThemeImages.GradientH("rule.fade", 64, S(0, C(0xE0B358, 0f)), S(.5f, C(0xF3D488, .95f)), S(1, C(0xE0B358, 0f)));
        public static readonly ThemeImage BarGloss = ThemeImages.Gradient("bar.gloss", 32, S(0, ThemeColor.White.WithAlpha(.42f)), S(.5f, ThemeColor.White.WithAlpha(.10f)), S(.52f, ThemeColor.White.WithAlpha(0f)), S(1, ThemeColor.Black.WithAlpha(.28f)));
        public static readonly ThemeImage HudGlass = ThemeImages.Gradient("glass.hud", 64, S(0, C(0x131B28, .975f)), S(.55f, C(0x080C14, .975f)), S(1, C(0x03050A, .985f)));
        public static readonly ThemeImage RowGlass = ThemeImages.Gradient("glass.row", 32, S(0, C(0x101722, .96f)), S(1, C(0x070A10, .96f)));
        public static readonly ThemeImage ShadeDown = ThemeImages.Gradient("shade.down", 32, S(0, C(0x000000, .58f)), S(.4f, C(0x000000, .22f)), S(1, C(0x000000, 0f)));
        public static readonly ThemeImage PlateFade = ThemeImages.GradientH("plate.fade", 64, S(0, C(0x03050A, 0f)), S(.18f, C(0x03050A, .78f)), S(.82f, C(0x03050A, .78f)), S(1, C(0x03050A, 0f)));
        public static readonly ThemeImage BarTrough = ThemeImages.Gradient("bar.trough", 32, S(0, C(0x000000, .86f)), S(.5f, C(0x04060A, .8f)), S(1, C(0x0B0F16, .8f)));
    }
